#include <iostream>
#include <stdexcept>

int share(int apples, int people) {
    if (people == 0) throw std::invalid_argument("Need at least one person");
    return apples / people;
}

int main() {
    try { std::cout << share(6, 0) << "\n"; }
    catch (const std::invalid_argument& error) { std::cout << error.what() << "\n"; }
}

